/**
 * Sub-barri overrides where one barri holds two fabrics that render very
 * differently. Coarse hand-drawn rings, [lat, lon] pairs, tested first.
 * `barris` restricts a zone to points inside those barris (null = any).
 */
export interface TypologyZone {
  readonly id: string
  readonly typology: UrbanTypology
  readonly barris: readonly string[] | null
  readonly ring: readonly (readonly [number, number])[]
}

