// ── Rendering profiles ────────────────────────────────────────────────────────

/** Linear RGB-ish triple in 0..1 (sRGB values; convert as the renderer needs). */
export type RGB = readonly [number, number, number]

export interface TypologyProfile {
  /** Typical storey count range INCLUDING ground floor, and the default when a building has no height/levels. */
  readonly storeys: { readonly min: number; readonly max: number; readonly default: number }
  /** Floor-to-floor height of the ground floor ("planta baixa"), m. */
  readonly groundFloorHeightM: number
  /** Floor-to-floor height of upper storeys, m. */
  readonly upperStoreyHeightM: number
  /** 5–8 realistic facade tones for this fabric. */
  readonly facadePalette: readonly RGB[]
  /** Shutter ("persiana") tone. */
  readonly shutterTone: RGB
  /** Window frame / carpentry tone. */
  readonly windowFrameTone: RGB
  /** Window (or balcony door) width, m. */
  readonly windowWidthM: number
  /** Bay = centre-to-centre window spacing, m. */
  readonly bayM: number
  readonly balcony: { readonly probability: number; readonly depthM: number }
  /** Stepped-back top floor ("àtic"): chance and setback from the facade line. */
  readonly attic: { readonly probability: number; readonly setbackM: number }
  readonly roof: {
    /** Probability a roof is a flat walkable "terrat" rather than pitched. */
    readonly flatTerraceProbability: number
    readonly tones: readonly RGB[]
    /** Parapet ("barana de terrat") height, m. */
    readonly parapetHeightM: number
  }
  /**
   * Cerdà block rule: the built strip is `buildableDepthM` deep from the facade
   * line; deeper than that is the block interior ("interior d'illa"), typically
   * ground floor only at `interiorGroundFloorHeightM`. null outside the grid.
   */
  readonly cerdaBlock: { readonly buildableDepthM: number; readonly interiorGroundFloorHeightM: number } | null
}

// Shared tones. "Verd Barcelona" is the dark green of wooden persianes seen on
// most pre-1970 facades; later estates use aluminium roller shutters.
const VERD_PERSIANA: RGB = [0.24, 0.36, 0.28]
const DARK_WOOD: RGB = [0.30, 0.22, 0.16]
const ALUMINIUM: RGB = [0.70, 0.71, 0.72]
const ROLLER_BEIGE: RGB = [0.66, 0.62, 0.52]
const TERRAT_TILE: RGB = [0.70, 0.50, 0.38] // "rajola de terrat" (red clay tile)
const CEMENT_GREY: RGB = [0.62, 0.61, 0.58]
const ROOF_WHITE: RGB = [0.86, 0.86, 0.84] // waterproofing membranes
const ARAB_TILE: RGB = [0.64, 0.38, 0.28] // "teula àrab" pitched roofs

