export function typologyProfile(t: UrbanTypology): TypologyProfile {
  return TYPOLOGY_PROFILES[t]
}

// ── Lookup ─────────────────────────────────────────────────────────────────────

/** Is the point inside the municipality's bbox? A cheap prefilter, not a polygon test. */
export function isBarcelona(lat: number, lon: number): boolean {
  return lat >= BCN_BBOX[0] && lat <= BCN_BBOX[2] && lon >= BCN_BBOX[1] && lon <= BCN_BBOX[3]
}

export interface BarriHit {
  readonly barri: string
  readonly district: string
  readonly typology: UrbanTypology
  /** Official barri number 1..73. */
  readonly code: number
  /** Id of the TYPOLOGY_ZONES entry that overrode the barri's typology, if any. */
  readonly zone: string | null
}

interface DecodedBarri {
  readonly name: string
  readonly code: number
  readonly district: string
  /** Rings as interleaved [lat, lon, lat, lon, …] degrees. */
  readonly rings: readonly Float64Array[]
  readonly minLat: number
  readonly minLon: number
  readonly maxLat: number
  readonly maxLon: number
}

// Decoding the constant data is pure and deterministic; caching it is safe.
let decoded: readonly DecodedBarri[] | null = null

function decode(): readonly DecodedBarri[] {
  if (decoded) return decoded
  decoded = BCN_BARRIS.map((b) => {
    let minLat = Infinity, minLon = Infinity, maxLat = -Infinity, maxLon = -Infinity
    const rings = b.r.map((enc) => {
      const out = new Float64Array(enc.length)
      let la = 0, lo = 0
      for (let i = 0; i < enc.length; i += 2) {
        la += enc[i]; lo += enc[i + 1]
        const lat = la / 1e5, lon = lo / 1e5
        out[i] = lat; out[i + 1] = lon
        if (lat < minLat) minLat = lat
        if (lat > maxLat) maxLat = lat
        if (lon < minLon) minLon = lon
        if (lon > maxLon) maxLon = lon
      }
      return out
    })
    return { name: b.n, code: b.c, district: BCN_DISTRICTS[b.d], rings, minLat, minLon, maxLat, maxLon }
  })
  return decoded
}

/** Every barri's decoded rings as [lat, lon][] — for tests and debug overlays. */
export function barriRings(): { barri: string; district: string; rings: [number, number][][] }[] {
  return decode().map((b) => ({
    barri: b.name,
    district: b.district,
    rings: b.rings.map((r) => {
      const pts: [number, number][] = []
      for (let i = 0; i < r.length; i += 2) pts.push([r[i], r[i + 1]])
      return pts
    }),
  }))
}

/** Even-odd point-in-polygon over interleaved rings. */
function inRings(lat: number, lon: number, rings: readonly Float64Array[]): boolean {
  let inside = false
  for (const r of rings) {
    const n = r.length
    for (let i = 0, j = n - 2; i < n; j = i, i += 2) {
      const ay = r[i], ax = r[i + 1], by = r[j], bx = r[j + 1]
      if ((ay > lat) !== (by > lat) && lon < ((bx - ax) * (lat - ay)) / (by - ay) + ax) inside = !inside
    }
  }
  return inside
}

function inZone(lat: number, lon: number, ring: readonly (readonly [number, number])[]): boolean {
  let inside = false
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const [ay, ax] = ring[i], [by, bx] = ring[j]
    if ((ay > lat) !== (by > lat) && lon < ((bx - ax) * (lat - ay)) / (by - ay) + ax) inside = !inside
  }
  return inside
}

/** Typology of a named barri (no zone overrides); 'mixed-urban' for an unknown name. */
export function barriTypology(barri: string): UrbanTypology {
  return BARRI_TYPOLOGY[barri] ?? 'mixed-urban'
}

/** Barri, district and typology at a point, or null outside Barcelona's barris. */
export function barriAt(lat: number, lon: number): BarriHit | null {
  if (!isBarcelona(lat, lon)) return null
  for (const b of decode()) {
    if (lat < b.minLat || lat > b.maxLat || lon < b.minLon || lon > b.maxLon) continue
    if (!inRings(lat, lon, b.rings)) continue
    let typology = barriTypology(b.name)
    let zone: string | null = null
    for (const z of TYPOLOGY_ZONES) {
      if (z.barris && !z.barris.includes(b.name)) continue
      if (inZone(lat, lon, z.ring)) { typology = z.typology; zone = z.id; break }
    }
    return { barri: b.name, district: b.district, typology, code: b.code, zone }
  }
  return null
}
